package com.islamicknowledge.platform.feature.dua

internal val DUAS: List<DuaItem> = listOf(
    DuaItem("sayyidul-istighfar", "MORNING_EVENING", "সাইয়্যিদুল ইস্তিগফার (ক্ষমা প্রার্থনার শ্রেষ্ঠ দোয়া)", "اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ", "হে আল্লাহ! আপনি আমার রব, আপনি ছাড়া কোনো সত্য উপাস্য নেই। আপনি আমাকে সৃষ্টি করেছেন এবং আমি আপনার বান্দা। আমি আমার সাধ্যমতো আপনার অঙ্গীকার ও প্রতিশ্রুতির ওপর অবিচল আছি। আমি যা কিছু করেছি তার অনিষ্ট থেকে আপনার কাছে আশ্রয় চাচ্ছি। আমার প্রতি আপনার নেয়ামত আমি স্বীকার করছি এবং আমার গুনাহও স্বীকার করছি। অতএব আমাকে ক্ষমা করে দিন; কারণ আপনি ছাড়া গুনাহ মাফ করার কেউ নেই।", "সহীহ বুখারী: ৬৩০৬", 1),
    DuaItem("ayatul-kursi", "MORNING_EVENING", "আয়াতুল কুরসী (সর্বশ্রেষ্ঠ সুরক্ষা আয়াত)", "اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَّهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَن ذَا الَّذِي يَشْفَعُ عِندَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ", "আল্লাহ, যিনি ব্যতীত কোনো সত্য উপাস্য নেই; তিনি চিরঞ্জীব, সর্বসত্তার ধারক। তন্দ্রা ও নিদ্রা তাঁকে স্পর্শ করে না। আসমান ও জমিনে যা কিছু আছে সব তাঁরই। কে সেই ব্যক্তি যে তাঁর অনুমতি ছাড়া তাঁর কাছে সুপারিশ করবে? তাদের সামনে ও পেছনে যা কিছু আছে তা তিনি জানেন। আর তাঁর জ্ঞানের কোনো কিছুই তারা আয়ত্ত করতে পারে না কেবল তিনি যা ইচ্ছে করেন তা ছাড়া। তাঁর কুরসী আসমানসমূহ ও জমিন পরিব্যাপ্ত করে আছে, আর এ দুটির রক্ষণাবেক্ষণ তাঁকে বিন্দুমাত্র ক্লান্ত করে না। তিনিই সর্বোচ্চ, মহান।", "সূরা আল-বাকারাহ: ২৫৫, নাসায়ী: ৯৯২৮ (সহীহ)", 1),
    DuaItem("bismillahillazi-la-yadurru", "MORNING_EVENING", "সকল ক্ষতি ও অনিষ্ট থেকে বাঁচার দোয়া", "بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ", "আল্লাহর নামে (শুরু করছি), যাঁর নামের বরকতে জমিন ও আসমানে কোনো বস্তুই ক্ষতি করতে পারে না। আর তিনি সর্বশ্রোতা, সর্বজ্ঞ।", "সুনানে আবু দাউদ: ৫০৮৮, জামে আত-তিরমিযী: ৩৩৮৮ (সহীহ)", 3),
    DuaItem("radheetu-billah", "MORNING_EVENING", "আল্লাহকে রব হিসেবে মেনে নেওয়ার দোয়া", "رَضِيتُ بِاللَّهِ رَبًّا، وَبِالْإِسْلَامِ دِينًا، وَبِمُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَبِيًّا", "আমি সন্তুষ্টচিত্তে আল্লাহকে রব হিসেবে, ইসলামকে দ্বীন হিসেবে এবং মুহাম্মদ ﷺ-কে নবী হিসেবে গ্রহণ করেছি।", "সুনানে আবু দাউদ: ৫০৭৪, জামে আত-তিরমিযী: ৩৩৮৯ (সহীহ)", 3),
    DuaItem("asbahna-wa-asbahal-mulk", "MORNING_EVENING", "সকালে আল্লাহর রাজত্ব ও সাহায্য প্রার্থনা", "أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذَا الْيَوْمِ وَخَيْرَ مَا بَعْدَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذَا الْيَوْمِ وَشَرِّ مَا بَعْدَهُ", "আমরা সকালে উপনীত হয়েছি এবং সমস্ত রাজত্বও আল্লাহর জন্য সকালে উপনীত হয়েছে। সমস্ত প্রশংসা আল্লাহর। এক আল্লাহ ব্যতীত কোনো উপাস্য নেই, তাঁর কোনো শরিক নেই। রাজত্ব একমাত্র তাঁরই এবং প্রশংসাও তাঁরই। তিনি সর্ববিষয়ে সর্বশক্তিমান। হে আমার রব! আমি আপনার নিকট আজকের এবং এর পরবর্তী দিনগুলোর কল্যাণ চাই এবং আজকের ও পরবর্তী দিনগুলোর অনিষ্ট থেকে আশ্রয় চাই।", "সহীহ মুসলিম: ২৭২৩", 1),
    DuaItem("ya-hayyu-ya-qayyum", "MORNING_EVENING", "সকল অবস্থা সংশোধনের মহিমান্বিত দোয়া", "يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ، أَصْلِحْ لِي شَأْنِي كُلَّهُ، وَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ", "হে চিরঞ্জীব, হে সর্বসত্তার ধারক! আপনার রহমতের উসিলায় সাহায্য প্রার্থনা করছি; আপনি আমার সকল কাজকর্ম শুধরে দিন এবং এক পলকের জন্যও আমাকে আমার নিজের ওপর ছেড়ে দেবেন না।", "সুনানে নাসায়ী কুবরা: ৩৮১, হাকেম: ১৮৮০ (সহীহ)", 1),
    DuaItem("subhanallahi-adada-khalqih", "MORNING_EVENING", "সৃষ্টির পরিমাণের চেয়েও ভারী তাসবীহ", "سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، عَدَدَ خَلْقِهِ، وَرِضَا نَفْسِهِ، وَزِنَةَ عَرْشِهِ، وَمِدَادَ كَلِمَاتِهِ", "আল্লাহর সপ্রশংস পবিত্রতা ঘোষণা করছি তাঁর সৃষ্টির সংখ্যার সমপরিমাণ, তাঁর নিজের সন্তুষ্টির সমপরিমাণ, তাঁর আরশের ওজনের সমপরিমাণ এবং তাঁর বাক্যসমূহের কালির সমপরিমাণ।", "সহীহ মুসলিম: ২৭২৬", 3),
    DuaItem("sleep-before", "SLEEP", "ঘুমানোর সময় পঠিত দোয়া", "بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا", "হে আল্লাহ! আপনার নামেই আমি মৃত্যুবরণ করছি (ঘুমাচ্ছি) এবং আপনার নামেই জীবিত (জাগ্রত) হব।", "সহীহ বুখারী: ৬৩১২, সহীহ মুসলিম: ২৭১১", 1),
    DuaItem("wake-up", "SLEEP", "ঘুম থেকে জাগ্রত হওয়ার দোয়া", "الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ", "যাবতীয় প্রশংসা সেই আল্লাহর, যিনি মৃত্যুর (ঘুমের) পর আমাদের পুনরায় জীবন দান করলেন। আর তাঁরই নিকট আমাদের পুনরুত্থান হবে।", "সহীহ বুখারী: ৬৩১২", 1),
    DuaItem("post-salah-astaghfirullah", "PRAYER_SALAH", "সালাম ফেরানোর পর ইস্তিগফার ও শান্তি প্রার্থনা", "أَسْتَغْفِرُ اللَّهَ (ثَلَاثًا)، اللَّهُمَّ أَنْتَ السَّلَامُ وَمِنْكَ السَّلَامُ، تَبَارَكْتَ يَا ذَا الْجَلَالِ وَالإِكْرَامِ", "আমি আল্লাহর নিকট ক্ষমা প্রার্থনা করছি (৩ বার)। হে আল্লাহ! আপনিই শান্তিময় এবং আপনার নিকট থেকেই শান্তি আসে। হে মহিমাময় ও সম্মানের অধিকারী! আপনি বরকতময়।", "সহীহ মুসলিম: ৫৯১", 1),
    DuaItem("post-salah-tasbeeh-fatimi", "PRAYER_SALAH", "নামাজ পরবর্তী ৩৩+৩৩+৩৪ তাসবীহ", "سُبْحَانَ اللَّهِ (٣٣)، الْحَمْدُ لِلَّهِ (٣٣)، اللَّهُ أَكْبَرُ (٣٣/٣٤)", "আল্লাহ অতি পবিত্র (৩৩ বার), সমস্ত প্রশংসা আল্লাহর (৩৩ বার), আল্লাহ সর্বশ্রেষ্ঠ (৩৩/৩৪ বার)।", "সহীহ মুসলিম: ৫৯৭", 100),
